/* From Uiverse.io by catraco - Tags: button, click, light&dark, startbutton  */
.__UIV_SCOPE__ .btn {
  --color: #de5c9d;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all .5s;
  border: none;
  background-color: transparent;
}

.__UIV_SCOPE__ .btn div {
  letter-spacing: 2px;
  font-weight: bold;
  background: var(--color);
  border-radius: 2rem;
  color: white;
  padding: 1rem;
}

.__UIV_SCOPE__ .btn::before {
  content: '';
  z-index: -1;
  background-color: var(--color);
  border: 2px solid white;
  border-radius: 2rem;
  width: 110%;
  height: 100%;
  position: absolute;
  transform: rotate(10deg);
  transition: .5s;
  opacity: 0.2;
}

.__UIV_SCOPE__ .btn:hover {
  cursor: pointer;
  filter: brightness(1.2);
  transform: scale(1.1);
}

.__UIV_SCOPE__ .btn:hover::before {
  transform: rotate(0deg);
  opacity: 1;
}

.__UIV_SCOPE__ .btn svg {
  transform: translateX(-200%);
  transition: .5s;
  width: 0;
  opacity: 0;
}

.__UIV_SCOPE__ .btn:hover svg {
  width: 25px;
  transform: translateX(0%);
  opacity: 1;
}

.__UIV_SCOPE__ .btn:active {
  filter: brightness(1.4);
}
